<script lang="ts">
 import HelpTip from './HelpTip.svelte';
 import {api} from '$lib/api';
 import {voiceTemplate,sectionRange,type StyleLayer} from '$lib/style';
 import Markdown from './Markdown.svelte';
 export let card:any;
 export let onChanged:()=>Promise<void>;
 export let onLibrary:(save?:boolean)=>void;
 export let onRun:(flow:string,text:string)=>Promise<void>;
 export let onOpen:(c:any)=>void;
 let loaded='',presets:any[]=[],characters:any[]=[],usage:any[]=[],layers:StyleLayer[]=[],preset='',pov='',notes='',error='',busy=false;
 $: key=card.id+':'+card.rev;
 $: if(key!==loaded){loaded=key;void load();}
 async function load(){const target=card;const keyAtStart=key;try{const [cards,links]=await Promise.all([api(`/novels/${target.novel_id}/cards`),api(`/cards/${target.id}/links`)]);if(keyAtStart!==key)return;presets=cards.filter((c:any)=>c.type==='style'&&c.subtype==='preset');characters=cards.filter((c:any)=>c.type==='character');preset=links.find((l:any)=>l.direction==='out'&&l.label==='uses_style')?.to_id||(target.type==='scene'?(target.fields.stylePresetMode==='none'?'none':'inherit'):'none');pov=links.find((l:any)=>l.direction==='out'&&l.label==='POV')?.to_id||'';notes=target.fields.styleNotes||'';if(['chapter','scene'].includes(target.type))layers=await api(`/novels/${target.novel_id}/style/resolve?scope=${target.id}`);if(target.type==='style'&&target.subtype==='preset')usage=await api(`/style/${target.id}/usage`);}catch(e:any){error=e.message;}}
 async function change(kind:string){busy=true;error='';try{if(kind==='pov')await api(`/scenes/${card.id}/pov`,'PUT',{characterId:pov||null,baseRev:card.rev});else await api(`/cards/${card.id}/style`,'PUT',{baseRev:card.rev,...(kind==='notes'?{styleNotes:notes}:{mode:['inherit','none'].includes(preset)?preset:'preset',presetId:['inherit','none'].includes(preset)?null:preset})});await onChanged();}catch(e:any){error=e.message;loaded='';}finally{busy=false;}}
 async function addVoice(){busy=true;try{await api(`/cards/${card.id}`,'PATCH',{baseRev:card.rev,body:card.body+(card.body.trim()?'\n\n':'')+voiceTemplate});await onChanged();}catch(e:any){error=e.message;}finally{busy=false;}}
</script>
<section class="style-controls">
 {#if error}<p role="alert" class="danger">{error}</p>{/if}
 {#if ['chapter','scene'].includes(card.type)}<h3>Style</h3><label>Preset<select aria-label="Style preset" bind:value={preset} disabled={busy} on:change={()=>change('preset')}>{#if card.type==='scene'}<option value="inherit">Inherit chapter</option>{/if}<option value="none">None</option>{#each presets as p}<option value={p.id}>{p.title}</option>{/each}</select></label><label>Style notes <HelpTip term="Style notes" text="Writing guidance for this scope, such as tone, sentence rhythm, imagery, or things to avoid. Describe how the prose should sound."/><textarea aria-label="Style notes" bind:value={notes} disabled={busy} on:blur={()=>{if(notes!==(card.fields.styleNotes||''))void change('notes');}}></textarea></label>
 {#if card.type==='scene'}<label>POV <HelpTip term="POV" text="Point of view: whose perspective the prose follows and how it is narrated, such as first person or close third person."/><select aria-label="POV character" bind:value={pov} disabled={busy} on:change={()=>change('pov')}><option value="">None</option>{#each characters as c}<option value={c.id}>{c.title}</option>{/each}</select></label>{/if}
 <button class="chip" on:click={()=>onLibrary()}>Choose from library</button><button class="chip" on:click={()=>onRun('recommend_style','Recommend three scene presets for this scene or chapter.')}>Recommend a style</button><details id="effective-style"><summary>Effective style · {layers.length} layers</summary>{#each layers as layer}<details><summary>{layer.kind.replaceAll('_',' ')} · {layer.sourceTitle}{layer.truncated?' · Samples shortened':''}</summary><button class="plain" on:click={()=>onOpen({id:layer.sourceCardId,type:layer.kind.includes('voice')||layer.kind==='pov_interior'?'character':layer.kind==='chapter_notes'?'chapter':layer.kind==='scene_notes'?'scene':'style'})}>Open source</button><Markdown text={layer.text}/></details>{:else}<p class="note">No style rules yet.</p>{/each}</details>
 {:else if card.type==='character'}<h3>Character voice <HelpTip term="Character voice" text="Guidance for how this character speaks or thinks. Use vocabulary, rhythm, habits, and perspective to distinguish their voice."/></h3>{#if !sectionRange(card.body,'Voice',2)}<button class="chip" disabled={busy} on:click={addVoice}>+ Add voice</button>{/if}<div class="actions"><button class="chip" on:click={()=>onLibrary()}>Choose from library</button><button class="chip" on:click={()=>onLibrary(true)}>Save voice to library</button><button class="chip" on:click={()=>onRun('voice_draft','Draft this character’s Voice section, preserving all other card text.')}>Draft this character’s voice</button><button class="chip" on:click={()=>onRun('recommend_style','Recommend three library voices for this character.')}>Recommend a voice</button></div>
 {:else if card.type==='style'}<h3>{card.subtype==='book'?'Book voice':'Preset'}</h3><div class="actions"><button class="chip" on:click={()=>onLibrary()}>Choose from library</button><button class="chip" on:click={()=>onLibrary(true)}>Save as library entry</button><button class="chip" on:click={()=>onRun('style_draft','Draft this style card from my story context.')}>Draft my {card.subtype==='book'?'book voice':'preset'}</button><button class="chip" on:click={()=>onRun('style_presets','Suggest reusable named presets for this book.')}>Suggest presets</button><button class="chip" on:click={()=>onRun('sample_rules','Turn sample passages in this card into observable style rules. Preserve samples.')}>Turn this sample into rules</button><button class="chip" on:click={()=>onRun('recommend_style','Recommend three library entries for this book.')}>Recommend a style</button></div>{#if card.subtype==='preset'}<h4>Used by · {usage.length}</h4>{#each usage as c}<button class="plain usage" on:click={()=>onOpen(c)}>{c.title} · {c.type}</button>{:else}<p class="note">No chapters or scenes use this preset yet.</p>{/each}{/if}
 {/if}
</section>
<style>
 .style-controls{border-bottom:1px solid var(--line);padding:16px 0;margin-bottom:16px}.style-controls h3{margin:0 0 12px;font:500 22px var(--serif)}label{display:block;margin:12px 0}select,textarea{width:100%;margin-top:6px;padding:9px 10px;border:1px solid var(--line);border-radius:5px;background:var(--paper);color:var(--ink);font:13px/1.5 var(--ui)}textarea{min-height:90px}details{margin:12px 0;overflow-wrap:anywhere}.usage{display:block;padding:5px 0}.actions{display:flex;gap:6px;flex-wrap:wrap}
</style>
